-- Idrok Business is for adults (18+). Run once after 0008.
-- Renames the guardian fields and rewrites the lessons that assumed an under-18 user.

alter table public.profiles rename column guardian_acknowledged to adult_confirmed;
alter table public.approvals rename column guardian_name to approver_name;

create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name, adult_confirmed)
  values (
    new.id,
    left(coalesce(new.raw_user_meta_data ->> 'full_name', ''), 80),
    coalesce((new.raw_user_meta_data ->> 'adult_confirmed')::boolean, false)
  )
  on conflict (id) do nothing;
  return new;
end;
$$;

-- Lessons generated from src/lib/lessons (account, supplier, payouts, account health, launch plan).
update public.lessons set data = '{"minutes":5,"icon":"shield","title":{"uz":"Sotuvchi hisobini ochish","ru":"Открытие аккаунта продавца"},"summary":{"uz":"Amazon va Uzum''da ro''yxatdan o''tish uchun nima kerak.","ru":"Что нужно для регистрации на Amazon и Uzum."},"slides":[{"kind":"learn","title":{"uz":"Hisob sizning nomingizda","ru":"Аккаунт на ваше имя"},"body":{"uz":"Sotuvchi hisobi sizning nomingizga ochiladi va undagi barcha ma''lumotlar haqiqiy bo''lishi kerak: ism, manzil, bank va soliq ma''lumotlari. Noto''g''ri ma''lumot hisob bloklanishiga va pul muzlatilishiga olib keladi.","ru":"Аккаунт продавца оформляется на ваше имя, и все данные в нём должны быть настоящими: имя, адрес, банк и налоговые данные. Неверные данные ведут к блокировке аккаунта и заморозке денег."},"visual":{"kind":"big","icon":"user","text":{"uz":"Haqiqiy ma''lumot = xavfsiz hisob","ru":"Настоящие данные = безопасный аккаунт"}}},{"kind":"learn","title":{"uz":"Ro''yxatdan o''tish uchun nima kerak","ru":"Что нужно для регистрации"},"body":{"uz":"Amazon odatda quyidagilarni so''raydi. Aniq ro''yxatni ro''yxatdan o''tish sahifasida tekshiring.","ru":"Обычно Amazon запрашивает следующее. Точный список проверьте на странице регистрации."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Shaxsni tasdiqlovchi hujjat (pasport)","ru":"Документ, удостоверяющий личность (паспорт)"},{"uz":"Xalqaro to''lovga yaroqli bank kartasi","ru":"Банковская карта для международных платежей"},{"uz":"Pul qabul qilinadigan bank hisobi","ru":"Банковский счёт для выплат"},{"uz":"Telefon raqami va email","ru":"Телефон и email"},{"uz":"Soliq ma''lumotlari","ru":"Налоговые данные"}]}},{"kind":"learn","title":{"uz":"Tasdiqlash jarayoni","ru":"Проверка личности"},"body":{"uz":"Amazon hujjatlaringizni tekshiradi, ba''zan video-qo''ng''iroq orqali. Bu bir necha kundan bir necha haftagacha davom etishi mumkin. Hujjatlardagi ism va manzil bir xil bo''lsin.","ru":"Amazon проверяет документы, иногда по видеозвонку. Это может занять от нескольких дней до нескольких недель. Имя и адрес во всех документах должны совпадать."}},{"kind":"learn","title":{"uz":"Uzum Market","ru":"Uzum Market"},"body":{"uz":"Uzum Market''da sotish uchun rasmiy ro''yxatdan o''tgan sotuvchi kerak, masalan yakka tartibdagi tadbirkor yoki kompaniya. Aniq talablarni Uzum''ning rasmiy sotuvchilar sahifasidan tekshiring.","ru":"Для продаж на Uzum Market нужен официально зарегистрированный продавец, например ИП или компания. Точные требования проверьте на официальной странице Uzum для продавцов."}},{"kind":"learn","title":{"uz":"Idrok sizni qanday himoya qiladi","ru":"Как Idrok вас защищает"},"body":{"uz":"Idrok faqat tadqiqot qiladi va tavsiya beradi. U pul sarflamaydi. Har bir xaridni Tasdiqlash markazida o''zingiz tekshirib tasdiqlaysiz va hammasi jurnalga yoziladi.","ru":"Idrok только исследует и советует. Он не тратит деньги. Каждую покупку вы сами проверяете и одобряете в Центре одобрений, и всё записывается в журнал."},"visual":{"kind":"flow","steps":[{"uz":"AI tavsiya","ru":"Совет ИИ"},{"uz":"Siz tekshirasiz","ru":"Вы проверяете"},{"uz":"Siz tasdiqlaysiz","ru":"Вы одобряете"}]}},{"kind":"quiz","question":{"uz":"Amazon sotuvchi hisobini ochishda odatda nima so''ralmaydi?","ru":"Что обычно НЕ требуется для аккаунта продавца Amazon?"},"options":[{"uz":"Pasport","ru":"Паспорт"},{"uz":"Bank hisobi","ru":"Банковский счёт"},{"uz":"Universitet diplomi","ru":"Диплом университета"}],"correct":2,"explain":{"uz":"Amazon shaxsingizni, bank va soliq ma''lumotlaringizni tekshiradi, ma''lumotingizni emas.","ru":"Amazon проверяет личность, банк и налоговые данные, а не образование."}}]}'::jsonb, updated_at = now() where id = 'account-age';
update public.lessons set data = '{"minutes":5,"icon":"globe","title":{"uz":"Yetkazib beruvchini topish","ru":"Поиск поставщика"},"summary":{"uz":"Ishonchli zavodni qanday tanlash.","ru":"Как выбрать надёжную фабрику."},"slides":[{"kind":"learn","title":{"uz":"Qayerdan izlash","ru":"Где искать"},"body":{"uz":"Ko''p sotuvchilar Xitoydagi ishlab chiqaruvchilarni Alibaba kabi platformalar orqali topadi. Bitta emas, bir nechta taklif oling.","ru":"Многие продавцы находят производителей в Китае через площадки вроде Alibaba. Берите не одно, а несколько предложений."},"visual":{"kind":"flow","steps":[{"uz":"Qidirish","ru":"Поиск"},{"uz":"3–5 ta taklif","ru":"3–5 предложений"},{"uz":"Solishtirish","ru":"Сравнение"},{"uz":"Namuna","ru":"Образец"}]}},{"kind":"learn","title":{"uz":"Yaxshi belgilar","ru":"Хорошие признаки"},"body":{"uz":"Bu belgilar kafolat emas, lekin xavfni kamaytiradi.","ru":"Это не гарантия, но риск меньше."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Platformada tasdiqlangan sotuvchi","ru":"Проверенный продавец на площадке"},{"uz":"Bir necha yillik tajriba","ru":"Несколько лет работы"},{"uz":"Savollarga tez va aniq javob","ru":"Быстрые и чёткие ответы"},{"uz":"Namuna yuborishga tayyor","ru":"Готов отправить образец"}]}},{"kind":"learn","title":{"uz":"Xavfli belgilar","ru":"Тревожные признаки"},"body":{"uz":"Bulardan birini ko''rsangiz, to''xtang va bu yetkazib beruvchi bilan ishlashdan oldin yaxshilab o''ylang.","ru":"Увидели одно из этого – остановитесь и хорошо подумайте, прежде чем работать с этим поставщиком."},"visual":{"kind":"checklist","tone":"bad","items":[{"uz":"Narx boshqalardan juda past","ru":"Цена намного ниже, чем у всех"},{"uz":"To''lovni shaxsiy kartaga so''raydi","ru":"Просит оплату на личную карту"},{"uz":"Savollarga noaniq javob","ru":"Уклончивые ответы"},{"uz":"Platformadan tashqarida to''lashga undaydi","ru":"Уговаривает платить вне площадки"}]}},{"kind":"quiz","question":{"uz":"Qaysi biri xavfli belgi?","ru":"Что из этого – тревожный признак?"},"options":[{"uz":"Namuna yuborishga tayyor","ru":"Готов отправить образец"},{"uz":"To''lovni shaxsiy kartaga so''raydi","ru":"Просит оплату на личную карту"},{"uz":"5 yillik tajriba","ru":"5 лет работы"}],"correct":1,"explain":{"uz":"Platformadan tashqari shaxsiy to''lovda pulingiz himoyalanmaydi.","ru":"При оплате на личную карту вне площадки ваши деньги не защищены."}}]}'::jsonb, updated_at = now() where id = 'find-supplier';
update public.lessons set data = '{"minutes":6,"icon":"shield","title":{"uz":"Pul olish va hisob-kitob","ru":"Выплаты и учёт"},"summary":{"uz":"Amazon qanday to''laydi va nimani yozib borish kerak.","ru":"Как платит Amazon и что записывать."},"slides":[{"kind":"learn","title":{"uz":"Amazon qanday to''laydi","ru":"Как платит Amazon"},"body":{"uz":"Amazon sotuvdan tushgan pulni to''lovlar va komissiyalarni ayirib, muntazam ravishda sotuvchi bank hisobiga o''tkazadi. To''lov jadvali va qo''llab-quvvatlanadigan davlatlarni Seller Central''da tekshiring.","ru":"Amazon регулярно переводит деньги с продаж на банковский счёт продавца, вычтя сборы и комиссии. График выплат и поддерживаемые страны смотрите в Seller Central."},"visual":{"kind":"flow","steps":[{"uz":"Sotuv","ru":"Продажа"},{"uz":"Komissiyalar ayiriladi","ru":"Вычет сборов"},{"uz":"Muntazam to''lov","ru":"Регулярная выплата"},{"uz":"Bank hisobi","ru":"Банковский счёт"}]}},{"kind":"learn","title":{"uz":"O''zbekistondan pul olish","ru":"Получение денег в Узбекистане"},"body":{"uz":"To''lov hisobi sizning nomingizda bo''ladi. Ba''zi sotuvchilar xalqaro to''lov xizmatlaridan foydalanadi. Qaysi usul ishlashini va komissiyalarini rasmiy manbalardan tekshiring.","ru":"Счёт для выплат оформляется на ваше имя. Некоторые продавцы используют международные платёжные сервисы. Какой способ работает и какие у него комиссии – проверяйте в официальных источниках."}},{"kind":"learn","title":{"uz":"Har bir so''mni yozib boring","ru":"Записывайте каждую сумму"},"body":{"uz":"Haqiqiy foydani bilish va soliqni to''g''ri hisoblash uchun barcha kirim va chiqimlarni saqlang. Soliq masalalarida mutaxassis bilan maslahatlashing.","ru":"Чтобы знать реальную прибыль и правильно считать налоги, сохраняйте все доходы и расходы. По налогам консультируйтесь со специалистом."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Zavod hisob-fakturalari","ru":"Счета фабрики"},{"uz":"Yetkazish va bojxona hujjatlari","ru":"Документы доставки и таможни"},{"uz":"Amazon to''lov hisobotlari","ru":"Отчёты о выплатах Amazon"},{"uz":"Reklama xarajatlari","ru":"Расходы на рекламу"}]}},{"kind":"learn","title":{"uz":"Idrok''da daraja","ru":"Уровень в Idrok"},"body":{"uz":"Keyingi darajaga o''tish uchun haqiqiy, hisobga tushgan sof foyda kerak. Administrator uni hujjatlar asosida tekshiradi, shuning uchun hisobotlarni saqlang.","ru":"Для перехода на следующий уровень нужна реальная чистая прибыль, полученная на счёт. Администратор проверяет её по документам, поэтому храните отчёты."}},{"kind":"quiz","question":{"uz":"Haqiqiy sof foydani bilish uchun nima kerak?","ru":"Что нужно, чтобы знать реальную чистую прибыль?"},"options":[{"uz":"Faqat sotuv summasi","ru":"Только сумма продаж"},{"uz":"Barcha kirim va chiqimlar yozuvi","ru":"Учёт всех доходов и расходов"},{"uz":"Sharhlar soni","ru":"Число отзывов"}],"correct":1,"explain":{"uz":"Sof foyda = barcha kirim minus barcha chiqim.","ru":"Чистая прибыль = все доходы минус все расходы."}}]}'::jsonb, updated_at = now() where id = 'getting-paid';
update public.lessons set data = '{"minutes":5,"icon":"shield","title":{"uz":"Hisob salomatligi","ru":"Здоровье аккаунта"},"summary":{"uz":"Hisobni yopilishdan qanday saqlash.","ru":"Как не потерять аккаунт."},"slides":[{"kind":"learn","title":{"uz":"Amazon nimani kuzatadi","ru":"Что отслеживает Amazon"},"body":{"uz":"Amazon har bir sotuvchining ishini ko''rsatkichlar orqali kuzatadi. Ular yomonlashsa, hisob to''xtatilishi mumkin. Seller Central''dagi \"Account Health\" sahifasini muntazam tekshiring.","ru":"Amazon следит за работой продавца по показателям. Если они ухудшатся, аккаунт могут приостановить. Регулярно проверяйте страницу «Account Health» в Seller Central."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Buyurtma nuqsonlari darajasi (ODR) – 1% dan past","ru":"Доля проблемных заказов (ODR) – ниже 1%"},{"uz":"Qoidabuzarliklar yo''q","ru":"Нет нарушений правил"},{"uz":"Xaridorga 24 soat ichida javob","ru":"Ответ покупателю в течение 24 часов"}]}},{"kind":"learn","title":{"uz":"Nima xavfli","ru":"Что опасно"},"body":{"uz":"Ko''pchilik hisoblar shu sabablar tufayli muammoga uchraydi.","ru":"Чаще всего аккаунты страдают из-за этого."},"visual":{"kind":"checklist","tone":"bad","items":[{"uz":"Soxta sharhlar","ru":"Фейковые отзывы"},{"uz":"Birovning brendi yoki patentini buzish","ru":"Нарушение чужого бренда или патента"},{"uz":"Yolg''on tavsif","ru":"Ложное описание"},{"uz":"Bir kishiga bir nechta hisob","ru":"Несколько аккаунтов на одного человека"}]}},{"kind":"learn","title":{"uz":"Ogohlantirish kelsa","ru":"Если пришло предупреждение"},"body":{"uz":"Vahimaga tushmang. Xatni diqqat bilan o''qing, sababini tushuning, kerak bo''lsa mutaxassis bilan maslahatlashing va muddatida aniq javob bering.","ru":"Не паникуйте. Внимательно прочитайте письмо, поймите причину, при необходимости посоветуйтесь со специалистом и ответьте чётко и в срок."}},{"kind":"quiz","question":{"uz":"Qaysi biri hisob uchun xavfli?","ru":"Что опасно для аккаунта?"},"options":[{"uz":"Xaridorga tez javob berish","ru":"Быстро отвечать покупателю"},{"uz":"Bir kishiga bir nechta hisob ochish","ru":"Открыть несколько аккаунтов на одного человека"},{"uz":"Halol tavsif yozish","ru":"Писать честное описание"}],"correct":1,"explain":{"uz":"Amazon odatda bir sotuvchiga bitta hisobga ruxsat beradi.","ru":"Amazon обычно разрешает одному продавцу один аккаунт."}}]}'::jsonb, updated_at = now() where id = 'account-health';
update public.lessons set data = '{"minutes":8,"icon":"play","title":{"uz":"Birinchi ishga tushirish rejasi","ru":"План первого запуска"},"summary":{"uz":"G''oyadan birinchi sotuvgacha – barcha qadamlar.","ru":"Все шаги от идеи до первой продажи."},"slides":[{"kind":"learn","title":{"uz":"Butun yo''l","ru":"Весь путь"},"body":{"uz":"Barcha darslar bitta reja bo''lib birlashadi. Har bir qadamni tugatmasdan keyingisiga o''tmang.","ru":"Все уроки складываются в один план. Не переходите к следующему шагу, не закончив предыдущий."},"visual":{"kind":"flow","steps":[{"uz":"Tadqiqot","ru":"Исследование"},{"uz":"Yetkazib beruvchi","ru":"Поставщик"},{"uz":"Namuna","ru":"Образец"},{"uz":"Buyurtma","ru":"Заказ"},{"uz":"Sotuv","ru":"Продажа"}]}},{"kind":"learn","title":{"uz":"1-bosqich: tadqiqot","ru":"Этап 1: исследование"},"body":{"uz":"0-daraja qoidalariga mos mahsulot tanlang, talab va raqobatni tekshiring, kalit so''zlarni yig''ing va foydani hisoblang.","ru":"Выберите товар по правилам уровня 0, проверьте спрос и конкурентов, соберите ключевые слова и посчитайте прибыль."},"visual":{"kind":"checklist","tone":"good","items":[{"uz":"Qoidalarga mos","ru":"Подходит под правила"},{"uz":"Talab bor","ru":"Есть спрос"},{"uz":"Yaxshilash imkoni bor","ru":"Есть что улучшить"},{"uz":"Foyda ijobiy","ru":"Прибыль положительная"}]}},{"kind":"learn","title":{"uz":"2-bosqich: yetkazib beruvchi va namuna","ru":"Этап 2: поставщик и образец"},"body":{"uz":"3–5 ta taklif oling, solishtiring, namunani tekshiring. Har bir xaridni Tasdiqlash markazida o''zingiz tasdiqlaysiz.","ru":"Получите 3–5 предложений, сравните, проверьте образец. Каждую покупку вы одобряете сами в Центре одобрений."}},{"kind":"learn","title":{"uz":"3-bosqich: tayyorlash va jo''natish","ru":"Этап 3: подготовка и отправка"},"body":{"uz":"Brend, shtrix-kodlar, qadoqlash va yorliqlarni tayyorlang. Listingni yarating, jo''natma tuzing va ekspeditorga topshiring.","ru":"Подготовьте бренд, штрихкоды, упаковку и этикетки. Создайте карточку и поставку, передайте груз экспедитору."}},{"kind":"learn","title":{"uz":"4-bosqich: ishga tushirish va o''rganish","ru":"Этап 4: запуск и анализ"},"body":{"uz":"Narxni belgilang, kichik reklama bilan boshlang, sharhlarni to''g''ri yo''l bilan so''rang, zaxirani kuzating. Har hafta raqamlarni ko''rib, xulosa qiling.","ru":"Установите цену, начните с небольшой рекламы, честно просите отзывы, следите за запасом. Каждую неделю смотрите цифры и делайте выводы."},"visual":{"kind":"big","icon":"flame","text":{"uz":"Kichik boshlang, tez o''rganing, halol ishlang","ru":"Начните с малого, учитесь быстро, работайте честно"}}},{"kind":"quiz","question":{"uz":"Katta buyurtmadan oldin qaysi qadam albatta bo''lishi kerak?","ru":"Какой шаг обязателен перед большим заказом?"},"options":[{"uz":"Reklama byudjetini oshirish","ru":"Увеличить рекламный бюджет"},{"uz":"Namunani tekshirish va tasdiqlash","ru":"Проверить и одобрить образец"},{"uz":"Narxni eng past qilish","ru":"Поставить самую низкую цену"}],"correct":1,"explain":{"uz":"Namuna va tasdiqlash – pul sarflashdan oldingi asosiy himoya.","ru":"Образец и одобрение – главная защита перед тратой денег."}}]}'::jsonb, updated_at = now() where id = 'launch-plan';

